package com.srenterprises.controller; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import com.srenterprises.service.*; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/inventory") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','STAFF')") public class AdminInventoryController { final InventoryRepository inventory; final InventoryTransactionRepository txs; final UserRepository users; final AuditService audit; AdminInventoryController(InventoryRepository i,InventoryTransactionRepository t,UserRepository u,AuditService a){inventory=i;txs=t;users=u;audit=a;} record Adjust(@Min(-100000) @Max(100000) int change,@NotBlank String reason){} @GetMapping public Page<Inventory> list(@RequestParam(defaultValue="0") int page){return inventory.findAll(PageRequest.of(page,25));} @PutMapping("/{productId}") public Inventory adjust(@PathVariable UUID productId,@RequestBody Adjust r,Authentication auth){Inventory i=inventory.lockByProductId(productId).orElseThrow(()->new NoSuchElementException("Inventory not found"));if(i.quantity+r.change()<0)throw new IllegalArgumentException("Stock cannot fall below zero");int previous=i.quantity;i.quantity+=r.change();inventory.save(i);InventoryTransaction tx=new InventoryTransaction();tx.product=i.product;tx.actor=users.findByEmailIgnoreCase(auth.getName()).orElse(null);tx.previousQuantity=previous;tx.changeQuantity=r.change();tx.newQuantity=i.quantity;tx.reason=r.reason();txs.save(tx);audit.record("INVENTORY_ADJUSTED","PRODUCT",productId,"Stock changed by "+r.change()+": "+r.reason());return i;} }
